import{_ as o,o as t,c as r,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const c="/shots/06-request.png",u=JSON.parse('{"title":"요구사항 접수하기","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/requirements"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/requirements"}],["meta",{"property":"og:title","content":"요구사항 접수하기"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/requirements.md","filePath":"docs/requirements.md"}'),d={name:"docs/requirements.md"};function n(p,e,i,s,l,m){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="요구사항-접수하기" tabindex="-1">요구사항 접수하기 <a class="header-anchor" href="#요구사항-접수하기" aria-label="Permalink to &quot;요구사항 접수하기&quot;">​</a></h1><p>앞 장에서 프로젝트를 만들었습니다. 이제 dira에서 뭘 하고 싶은지 말해봅시다.</p><h2 id="요구-접수와-티켓-발행" tabindex="-1">요구 접수와 티켓 발행 <a class="header-anchor" href="#요구-접수와-티켓-발행" aria-label="Permalink to &quot;요구 접수와 티켓 발행&quot;">​</a></h2><p>보드 우상단에 버튼이 둘 있습니다. 오른쪽의 <code>요구 접수</code>가 정문이고, 왼쪽의 <code>티켓 발행</code>은 우회로입니다.</p><p><img src="'+c+'" alt="요구 접수 다이얼로그. 자연어를 적는 칸 하나와 접수 버튼뿐이고, kind·persona·deps를 고르는 칸이 없습니다."></p><p><code>티켓 발행</code>은 제목과 kind·persona·deps를 사람이 고릅니다. 무엇을 누가 어떤 순서로 할지 이미 아는 사람의 폼입니다. <code>요구 접수</code>는 자연어 한 칸뿐입니다. 쪼개서 쓸 필요가 없습니다. 원하시는 것을 원하시는 문장으로 쓰면, 쪼개는 일은 다음 절이 합니다.</p><ul><li>첫 줄이 제목이 됩니다(80자에서 잘립니다). 제목을 따로 쓰지 않습니다.</li><li>본문은 <strong>쓰신 전문 그대로</strong> 저장됩니다. 앱이 문장을 고쳐 쓰거나 골격을 채우지 않습니다.</li><li>프로젝트 안 어디서든 <code>r</code>을 누르면 이 칸이 열립니다. 버튼은 보드에만 있지만, 요구는 워커 화면을 보다가도 티켓을 읽다가도 생기기 때문입니다.</li><li>접수되면 <code>요구사항이 접수되었습니다. 곧 PM이 검토할 예정입니다.</code>가 그 자리에 뜹니다. 화면이 어디로 끌고 가지 않고, 아래 <code>접수한 요구 보기</code> 링크를 누르면 그 요구의 상세로 갑니다.</li></ul><h2 id="접수한-다음에-일어나는-일" tabindex="-1">접수한 다음에 일어나는 일 <a class="header-anchor" href="#접수한-다음에-일어나는-일" aria-label="Permalink to &quot;접수한 다음에 일어나는 일&quot;">​</a></h2><p>접수는 큐에 <code>kind: request</code> 티켓 한 장을 세웁니다. 담당은 <code>pm</code> 페르소나입니다.</p><p>1분 안에 pm 워커가 그 티켓을 물어 갑니다. pm 세션이 하는 일은 읽고 쪼개는 것입니다. 요구 하나가 작업 티켓 여러 장이 되고, 각 티켓은 페르소나가 정해지고 필요한 만큼 <code>deps</code>로 엮입니다. 쪼개진 티켓에는 <code>req:</code> 자리에 원본 요구의 해시가 박힙니다. 해시는 티켓마다 붙는 여덟 자리 이름입니다. 그래서 요구 상세에서 쪼개진 티켓들이 보이고, 티켓 상세에서 출처 요구로 돌아올 수 있습니다.</p><p>쪼개기가 끝나면 원본 요구는 <code>완료</code>가 됩니다. 그건 일이 끝났다는 뜻이 아니라 <strong>해석이 끝났다는 뜻</strong>입니다. 실제 일은 그 아래 티켓들에 있고, 각자 자기 페르소나 워커가 물어 갑니다.</p><h2 id="되묻기와-답변-대기" tabindex="-1">되묻기와 <code>답변 대기</code> <a class="header-anchor" href="#되묻기와-답변-대기" aria-label="Permalink to &quot;되묻기와 `답변 대기`&quot;">​</a></h2><p>pm이 쪼갤 수 없다고 판단하면 추측하지 않습니다. 질문을 남기고 손을 뗍니다.</p><p>그 요구는 보드에서 <code>답변 대기</code> 배지를 달고, 며칠이 지났는지가 배지에 같이 붙습니다. 요구 상세를 열면 스레드에 질문이 있고, 그 아래에 답을 쓰는 칸이 있습니다. 답을 쓰면 요구가 다시 <code>대기</code>로 돌아오고, pm 워커가 이번엔 그 답을 함께 읽고 이어 갑니다. 두 번 이상 물을 수도 있습니다. 질문과 답이 번호로 짝지어 스레드에 쌓입니다.</p><p>답이 달릴 때까지 그 요구는 아무 워커도 물어 가지 않습니다. 세션을 태우면서 같은 질문을 반복하지 않도록 잠가 둔 것입니다. 그래서 <code>답변 대기</code>는 고장이 아닙니다. 설계된 한 단계이고, 그 자리에서 멈춘 채 답을 기다립니다.</p><h2 id="쓰는-사람이-하는-일" tabindex="-1">쓰는 사람이 하는 일 <a class="header-anchor" href="#쓰는-사람이-하는-일" aria-label="Permalink to &quot;쓰는 사람이 하는 일&quot;">​</a></h2><p>요구를 넣으면 pm이 쪼개고, 페르소나별 워커가 각자 물어 갑니다. 막히는 자리에서 누군가 물으면 답하시면 됩니다. 티켓을 직접 쓰거나 누구에게 넘길지 정하는 일은 없습니다.</p><p>직접 쓰고 싶어질 때는 있습니다. 버그 하나, 오타 하나처럼 쪼갤 것이 없는 일입니다. 그건 <a href="/docs/ticket-writing">티켓 직접 발행하기</a>에 있습니다.</p><p>다음은 <a href="/docs/screens">화면 소개</a>입니다.</p>',19)])])}const _=o(d,[["render",n]]);export{u as __pageData,_ as default};
